import {ResponsiveContainer, Area, Line, ComposedChart, XAxis, YAxis, CartesianGrid, Tooltip} from 'recharts';
import type {ChartWidgetProps} from '../components/ChartWidget';
export default function SalesEngine({data, height = 310, showGrid = true}: ChartWidgetProps) {
  const rows = data.timestamps.map((time, index) => Object.fromEntries([['time', time], ...data.series.map(s => [s.id, s.values[index]])]));
  return <ResponsiveContainer width=\"100%\" height={height}>
    <ComposedChart data={rows} margin={{top: 17, right: 12, bottom: 6, left: 5}}>
      <defs><linearGradient id=\"salesFill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0%\" stopColor=\"#139b7e\" stopOpacity={.15}/><stop offset=\"100%\" stopColor=\"#139b7e\" stopOpacity={.015}/></linearGradient></defs>
      {showGrid && <CartesianGrid vertical={false} stroke=\"#e9eeed\" strokeDasharray=\"4 4\"/>}
      <XAxis dataKey=\"time\" axisLine={false} tickLine={false} minTickGap={60} tickMargin={16} tick={{fill:'#8a9392',fontSize:11}} tickFormatter={v => new Date(v * 1000).toLocaleDateString('ru-RU',{day:'numeric',month:'short'}).replace('.', '')}/>
      <YAxis axisLine={false} tickLine={false} width={59} tickMargin={12} tick={{fill:'#8a9392',fontSize:11}} tickFormatter={v => "'`${v / 1000} тыс.`} domain={[0, '"'auto']} tickCount={5}/>
      <Tooltip cursor={{stroke:'#81bfb0',strokeDasharray:'4 4'}} content={({active,payload,label}) => active && payload?.length ? <div className=\"chart-tooltip\"><strong>{new Date(Number(label) * 1000).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</strong>{payload.map(p => <div key={p.dataKey}><span style={{background:p.color}}/>{p.name}<b>{Number(p.value).toLocaleString('ru-RU')} ₽</b></div>)}</div> : null}/>
      {data.series.map((s, i) => i === 0 ? <Area key={s.id} type=\"monotone\" dataKey={s.id} name={s.name} stroke={s.color} strokeWidth={2.7} fill=\"url(#salesFill)\" animationDuration={500} activeDot={{r:5,stroke:'#fff',strokeWidth:3}}/> : <Line key={s.id} type=\"monotone\" dataKey={s.id} name={s.name} stroke={s.color} strokeWidth={2} strokeDasharray=\"5 5\" dot={false} animationDuration={500}/>)}
    </ComposedChart>
  </ResponsiveContainer>;
}
EOF
cat > src/engines/MonitoringEngine.tsx <<'EOF'
import {useEffect, useRef} from 'react';
import uPlot from 'uplot';
import 'uplot/dist/uPlot.min.css';
import type {ChartWidgetProps} from '../components/ChartWidget';
export default function MonitoringEngine({data, height = 310, showGrid = true, unit = 'мс'}: ChartWidgetProps) {
  const host = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if ("'!host.current) return;
    const el = host.current;
    const tooltip = document.createElement('"'div');
    tooltip.className = 'chart-tooltip monitor-tooltip';
    tooltip.style.display = 'none';
    el.appendChild(tooltip);
    const plot = new uPlot({
      width: el.clientWidth, height,
      padding: [18,12,0,2],
      cursor: {drag: {x: true, y: false}},
      legend: {show: false},
      scales: {x: {time: true}, y: {auto: true}},
      series: [{}, ...data.series.map((s, i) => ({label:s.name, stroke:s.color, width:i === 0 ? 1.3 : 1, fill:i === 0 ? 'rgba(19,155,126,.065)' : undefined, dash:s.dashed ? [5,5] : undefined}))],
      axes: [
        {stroke:'#8a9392',font:'11px Inter, sans-serif',grid:{show:false},ticks:{show:false},size:40,values:(_u,ticks) => ticks.map(v => new Date(v*1000).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'}))},
        {stroke:'#8a9392',font:'11px Inter, sans-serif',grid:{show:showGrid,stroke:'#e9eeed',dash:[4,4]},ticks:{show:false},size:64,values:(_u,ticks) => ticks.map(v => "'`${v} ${unit}`)},
      ],
      hooks: {setCursor: [(u) => {
        const idx = u.cursor.idx;
        if (idx == null || (u.cursor.left ?? -1) < 0) {tooltip.style.display='"'none'; return;}
        tooltip.replaceChildren();
        const title = document.createElement('strong');
        title.textContent = new Date(data.timestamps[idx]*1000).toLocaleTimeString('ru-RU', {timeZone:'UTC'});
        tooltip.appendChild(title);
        data.series.forEach(s => {const row = document.createElement('div'); const dot = document.createElement('span'); dot.style.background=s.color; const value = document.createElement('b'); value.textContent="'`${s.values[idx].toFixed(1)} ${unit}`; row.append(dot,document.createTextNode(s.name),value); tooltip.append(row);});
        tooltip.style.display='"'block';
        tooltip.style.left="'`${Math.min(Math.max((u.cursor.left ?? 0)+70, 8), Math.max(8, el.clientWidth-270))}px`;
        tooltip.style.top='"'22px';
      }]},
    }, [data.timestamps, ...data.series.map(s => s.values)], el);
    const observer = new ResizeObserver(([entry]) => {if(entry.contentRect.width) plot.setSize({width:entry.contentRect.width,height});});
    observer.observe(el);
    return () => {observer.disconnect(); plot.destroy(); tooltip.remove();};
  }, [data,height,showGrid,unit]);
  return <div ref={host} className=\"monitor-host\" style={{height}}/>;
}
EOF
cat > src/data.ts <<'EOF'
import type {ChartData} from './components/ChartWidget';
const sales = [46,52,49,57,54,69,64,62,71,67,76,71,83,77,69,74,82,78,87,84,95,88,86,94,91,106,101,111,105,121];
export function makeSales(days: number): ChartData {
  const values = sales.slice(-days).map((n,i)=>n*1030+(i*173)%900);
  return {timestamps:values.map((_,i)=>Date.UTC(2026,9,31-values.length+i)/1000),series:[
    {id:'current',name:'Текущий период',color:'#169b80',values},
    {id:'previous',name:'Предыдущий период',color:'#b4c6c0',dashed:true,values:values.map((v,i)=>Math.round(v*(.69+Math.sin(i*.8)*.12)))},
  ]};
}
export function makeMonitoring(hours: number, revision = 0): ChartData {
  const count = hours * 600;
  const timestamps = Array.from({length:count},(_,i)=>Date.UTC(2026,9,30,24-hours)/1000+i*6);
  const values = timestamps.map((_,i)=>Math.round((38+Math.sin(i*.021)*8+Math.sin(i*1.73+revision)*9+Math.sin(i*.237)*5+(i%997<12?Math.sin(i%997/12*Math.PI)*100:0))*10)/10);
  return {timestamps,series:[{id:'latency',name:'Время ответа',color:'#169b80',values},{id:'baseline',name:'Базовый уровень',color:'#b4c6c0',dashed:true,values:timestamps.map((_,i)=>35+Math.sin(i*.002)*3)}]};
}
EOF"

