import fs from 'node:fs';
let html=fs.readFileSync('index.html','utf8').replace('<title>Gravity UI eval</title>','<meta name=\"theme-color\" content=\"#169b80\" />\\n    <meta name=\"description\" content=\"Пульс — продажи и мониторинг в одном аналитическом виджете.\" />\\n    <title>Пульс — Обзор показателей</title>');
fs.writeFileSync('index.html',html);
let app=fs.readFileSync('src/App.tsx','utf8');
app=app.replace('ArrowLeft, ','').replace('Command, ','').replace('Plus, ','').replace('Radio, ','').replace(', Zap}', '}');
app=app.replace(\"const money =\", \"function readPreferences() {\\n  try {return JSON.parse(localStorage.getItem('pulse-preferences') || '{}');} catch {return {};}\\n}\\nconst initialPreferences = readPreferences();\\nconst money =\");
app=app.replace(\"useState<ChartMode>('sales')\", \"useState<ChartMode>(initialPreferences.mode === 'monitoring' ? 'monitoring' : 'sales')\");
app=app.replace('useState(30)', 'useState([7,14,30].includes(initialPreferences.salesDays) ? Number(initialPreferences.salesDays) : 30)');
app=app.replace('useState(24)', 'useState([1,6,24].includes(initialPreferences.monitorHours) ? Number(initialPreferences.monitorHours) : 24)');
app=app.replace('const [comparison,setComparison] = useState(true)', 'const [comparison,setComparison] = useState(initialPreferences.comparison "'!== false)'"');
app=app.replace('const [grid,setGrid] = useState(true)', 'const [grid,setGrid] = useState(initialPreferences.grid "'!== false)'"');
app=app.replace(\"const isSales = mode === 'sales';\", \"const isSales = mode === 'sales';\\n  const orderGrowth = ((Math.round(total/4250)/Math.round(previous/3965)-1)*100).toFixed(1).replace('.',',');\\n  useEffect(()=>{try {localStorage.setItem('pulse-preferences',JSON.stringify({mode,salesDays,monitorHours,comparison,grid}));}catch{}},[mode,salesDays,monitorHours,comparison,grid]);\");
app=app.replace(\"isSales?'+18,6%':'6 сек'\", \"isSales?"'`+${orderGrowth}%`:'"'6 сек'\");
fs.writeFileSync('src/App.tsx',app);
JS"

