import {useEffect, useMemo, useRef, useState} from 'react';
import {Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Bell, BookOpen, CalendarDays, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, Command, Database, FileChartColumn, Grid2X2, Layers3, LayoutDashboard, LineChart, Maximize2, MoreHorizontal, Plus, Radio, RefreshCw, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, TrendingUp, X, Zap} from 'lucide-react';
import {ChartWidget, type ChartMode} from './components/ChartWidget';
import {makeMonitoring, makeSales} from './data';
