  const visibleData = useMemo(()=>({...data,series:comparison?data.series:data.series.slice(0,1)}),[data,comparison]);
  const total = data.series[0].values.reduce((a,b)=>a+b,0);
  const previous = data.series[1].values.reduce((a,b)=>a+b,0);
  const growth = ((total/previous-1)*100).toFixed(1).replace('.',',');
  const isSales = mode === 'sales';
  useEffect(()=>{if("'!toast)return; const t=setTimeout(()=>setToast('"''),3500);return()=>clearTimeout(t);},[toast]);
  useEffect(()=>{const click=(e:MouseEvent)=>{if("'!dateRef.current?.contains(e.target as Node))setDateOpen(false);if(!settingsRef.current?.contains(e.target as Node))setSettingsOpen(false);};const key=(e:KeyboardEvent)=>{if(e.key==='"'Escape'){setPanel(null);setFullscreen(false);setDateOpen(false);setSettingsOpen(false);}};document.addEventListener('mousedown',click);document.addEventListener('keydown',key);return()=>{document.removeEventListener('mousedown',click);document.removeEventListener('keydown',key);};},[]);
  function exportData() {
    const header=['Дата (UTC)',...visibleData.series.map(s=>s.name)];
